#include <cstdio>
#include <cstdlib>
#include "tests/unit/dsp_stream_fixture.hpp"
namespace {unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"DSP stream: %s\n",why);std::abort();}}}
int main(){
    using namespace gf;std::string error;std::vector<s16> samples;u32 produced=0;DspStream stream;
    for(unsigned frames:{1u,13u,14u,15u,28u,29u,127u,4097u}){auto h=dsp_stream_fixture::header(frames),b=dsp_stream_fixture::payload(frames);DspAudio whole;check(dsp_adpcm_decode({h.data(),h.size()},{b.data(),b.size()},&whole,&error),"legacy declared-pass baseline");
        for(unsigned chunk:{1u,7u,14u,17u,127u,4096u}){check(stream.load({h.data(),h.size()},{b.data(),b.size()},DspStreamMode::DeclaredOnce,&error),"owned declared cursor");std::vector<s16> result;while(!stream.state().ended){check(stream.read(chunk,&samples,&produced,&error)&&produced==samples.size()&&produced<=chunk,"bounded produced prefix");result.insert(result.end(),samples.begin(),samples.end());}check(result==whole.samples&&stream.state().rendered==frames&&!stream.state().loops,"every chunking equals the legacy declared pass");check(stream.read(chunk,&samples,&produced,&error)&&samples.empty()&&produced==0,"end is empty, not fabricated silence/PCM");}
    }
    auto h=dsp_stream_fixture::header(28);std::vector<u8> b(16);store_be16(h.data()+28,2048);store_be16(h.data()+64,5);store_be16(h.data()+12,1);store_be32(h.data()+16,23);store_be16(h.data()+70,123);store_be16(h.data()+72,65534);
    check(stream.load({h.data(),h.size()},{b.data(),b.size()},DspStreamMode::HeaderPlayback,&error),"mid-frame compressed loop input");check(stream.read(46,&samples,&produced,&error)&&produced==46,"looped block spans three boundaries");check(std::vector<s16>(samples.begin(),samples.begin()+28)==std::vector<s16>(28,5)&&std::vector<s16>(samples.begin()+28,samples.end())==std::vector<s16>(18,123),"loop restores header histories, NOT repeated decoded PCM");check(stream.state().loops==3&&stream.state().position==19&&stream.state().history1==123&&stream.state().history2==-2,"post-boundary cursor normalized to stored loop context");
    auto clone=stream;std::vector<s16> other;check(clone.read(31,&other,nullptr,&error)&&stream.read(31,&samples,&produced,&error)&&other==samples&&clone.state()==stream.state(),"copy shares immutable compressed data, not mutable playback state");
    const auto state=stream.state();check(!stream.read(0,&samples,&produced,&error)&&stream.state()==state&&samples.empty()&&produced==0,"zero block refuses without consuming");check(!stream.read(4097,&samples,&produced,&error)&&stream.state()==state,"oversized block refuses without consuming");check(!stream.read(1,nullptr,&produced,&error)&&stream.state()==state,"missing output refuses without consuming");
    check(stream.restart()&&stream.state().position==0&&stream.state().history1==5&&!stream.state().loops,"explicit restart uses initial context, not loop context");
    auto shorter=h;store_be16(shorter.data()+12,0);store_be32(shorter.data()+16,2);store_be32(shorter.data()+20,15);check(stream.load({shorter.data(),shorter.size()},{b.data(),b.size()},DspStreamMode::HeaderPlayback,&error)&&stream.end_sample()==14&&stream.read(28,&samples,&produced,&error)&&produced==14&&stream.state().ended,"nonloop source nibble end is not declared trailing storage");
    check(stream.load({shorter.data(),shorter.size()},{b.data(),b.size()},DspStreamMode::DeclaredOnce,&error)&&stream.read(28,&samples,&produced,&error)&&produced==28,"declared-pass compatibility remains distinct from source addressed end");
    auto terminal=dsp_stream_fixture::header(28);store_be32(terminal.data()+4,34);auto padded=b;padded.resize(24,0);padded[16]=0xff;check(stream.load({terminal.data(),terminal.size()},{padded.data(),padded.size()},DspStreamMode::DeclaredOnce,&error)&&stream.read(100,&samples,&produced,&error)&&produced==28,"unused terminal header is not a frame/extra sample");
    for(unsigned position:{0u,8u}){auto bad=b;bad[position]=0x80;check(!stream.load({h.data(),h.size()},{bad.data(),bad.size()},DspStreamMode::HeaderPlayback,&error)&&!stream.ready()&&!stream.info(),"invalid early/later predictor invalidates old cursor");check(!stream.read(1,&samples,&produced,&error)&&samples.empty(),"failed load cannot replay prior PCM");}
    for(unsigned field:{0u,4u,8u,12u,14u,16u,20u,24u,60u,62u,68u}){auto bad=h;bad[field]^=0x80;check(!stream.load({bad.data(),bad.size()},{b.data(),b.size()},DspStreamMode::HeaderPlayback,&error)&&!stream.ready(),"metadata/context domain guard");}
    check(!stream.load({h.data(),h.size()},{nullptr,b.size()},DspStreamMode::HeaderPlayback,&error),"null payload");check(!stream.load({h.data(),h.size()},{b.data(),b.size()},static_cast<DspStreamMode>(99),&error),"unknown playback mode");
    h=dsp_stream_fixture::header(14);b=dsp_stream_fixture::payload(14);check(stream.load({h.data(),h.size()},{b.data(),b.size()},DspStreamMode::DeclaredOnce,&error),"fresh owned input");h.clear();b.clear();check(stream.read(14,&samples,&produced,&error)&&produced==14,"cursor owns metadata and compressed bytes");auto moved=std::move(stream);check(moved.ready()&&!stream.ready()&&moved.state().ended,"move transfers owned playback without stale source cursor");
    std::printf("{\"dsp_stream_owned_checks\":%u,\"all_passed\":true}\n",checks);
}
